import {clamp,reflex} from './core.js';
// Real MaleCNS connectivity; intentionally artificial game sensors and motor decoder.
// Continuous rates below are dimensionless model values, not measured spike rates.
export class CircuitPilot {
 constructor(graph){this.graph=graph;const n=graph.units.count;this.rates=new Float32Array(n);this.drive=new Float32Array(n);this.next=new Float32Array(n);this.inputs=[[],[]];this.outputs=[[],[]];this.left=0;this.right=0;this.cooldown=0;this.thought='Avoid becoming a wall decoration.';this.stimulus=[0,0];this.pre=Uint16Array.from(graph.edges.pre);this.post=Uint16Array.from(graph.edges.post);this.weights=new Float32Array(graph.edges.count);const incoming=new Float32Array(n);for(let e=0;e<this.pre.length;e++)incoming[this.post[e]]+=graph.edges.weight[e];for(let e=0;e<this.pre.length;e++)this.weights[e]=1.2*graph.units.sign[this.pre[e]]*graph.edges.weight[e]/Math.max(1,incoming[this.post[e]]);for(let i=0;i<n;i++){const type=graph.types[graph.units.type[i]].name;const side=graph.units.side[i]==='L'?0:graph.units.side[i]==='R'?1:-1;if(side<0)continue;if(/^(LC4|LPLC2)$/.test(type))this.inputs[side].push(i);if(/^DNp0[1-6]$/.test(type))this.outputs[side].push(i);}}
 reset(){this.rates.fill(0);this.cooldown=0;this.left=0;this.right=0;}
 simulate(left,right,steps=3){this.stimulus=[left,right];for(let s=0;s<steps;s++){this.drive.fill(0);for(const i of this.inputs[0])this.drive[i]=left;for(const i of this.inputs[1])this.drive[i]=right;for(let e=0;e<this.pre.length;e++)this.drive[this.post[e]]+=this.weights[e]*this.rates[this.pre[e]];for(let i=0;i<this.rates.length;i++)this.next[i]=clamp(this.rates[i]+.3*(this.drive[i]-this.rates[i]),0,3);[this.rates,this.next]=[this.next,this.rates];}this.left=this.outputs[0].reduce((a,i)=>a+this.rates[i],0)/this.outputs[0].length/1.95;this.right=this.outputs[1].reduce((a,i)=>a+this.rates[i],0)/this.outputs[1].length/1.388;}
 update(observation,dt=.05,active=true){const o=observation;this.cooldown=Math.max(0,this.cooldown-dt);const danger=[0,0,0];for(const b of o.obstacles){const t=b.distance/o.speed;if(t<1.6){const value=clamp((1.6-t)/1.15,0,1.6)*(b.type==='block'?1:.55);danger[b.lane]=Math.max(danger[b.lane],value);}}const own=danger[o.lane];const left=o.lane===0?1.4:danger[o.lane-1];const right=o.lane===2?1.4:danger[o.lane+1];let l=.04+own*.6+left*1.7,r=.04+own*.6+right*1.7;const nearest=o.sugar[0];const sugar=nearest&&nearest.distance/o.speed<1.8&&nearest.distance/o.speed>.55?nearest:null;if(sugar&&own<.1){if(sugar.lane<o.lane)r+=.5;if(sugar.lane>o.lane)l+=.5;}this.simulate(l,r);if(!active){this.thought='Your hands. Its tiny nervous system.';return'none';}const front=o.obstacles.find(b=>b.lane===o.lane&&b.distance/o.speed<.65);const ref=reflex(o);if(ref!=='none'){this.thought=ref==='jump'?'Wings are decorative. JUMP.':'Become a slightly flatter fly.';this.cooldown=.35;return ref;}if(this.cooldown>0)return'none';if(front&&front.type==='block'||(sugar&&own<.1&&sugar.lane!==o.lane)){const difference=this.left-this.right;let action=difference>0?'right':'left';if((action==='left'&&o.lane===0)||(action==='right'&&o.lane===2))return'none';if(!front&&danger[o.lane+(action==='left'?-1:1)]>.1)return'none';this.thought=front?'Large object. Very small life.':'Sugar is a perfectly good life goal.';this.cooldown=.3;return action;}this.thought=front?'Calculating a questionable escape.':own>.1?'Staying extremely un-swatted.':'Sugar is a perfectly good life goal.';return'none';}
}



